import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"33、【遁】 艮下乾上","description":"橫渠易說 - 33、【遁】 艮下乾上","frontmatter":{"title":"33、【遁】 艮下乾上","description":"橫渠易說 - 33、【遁】 艮下乾上"},"headers":[],"relativePath":"classics/hengqu/035.md","filePath":"classics/hengqu/035.md"}'),l={name:"classics/hengqu/035.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_33、【遁】-艮下乾上" tabindex="-1">33、【遁】 艮下乾上 <a class="header-anchor" href="#_33、【遁】-艮下乾上" aria-label="Permalink to “33、【遁】 艮下乾上”">​</a></h1><h3 id="彖曰-遁亨-遁而亨也-剛當位而應-與時行也。-小利貞-浸而長也。遁之時義大矣哉" tabindex="-1">彖曰：“遁亨”，遁而亨也，剛當位而應，與時行也。“小利貞”，浸而長也。遁之時義大矣哉! <a class="header-anchor" href="#彖曰-遁亨-遁而亨也-剛當位而應-與時行也。-小利貞-浸而長也。遁之時義大矣哉" aria-label="Permalink to “彖曰：“遁亨”，遁而亨也，剛當位而應，與時行也。“小利貞”，浸而長也。遁之時義大矣哉!”">​</a></h3><p>當位而應，理不當遁，以陰長故遁，故曰“與時行”，又曰“小利貞”，又曰“遁而亨”也。</p><h3 id="象曰-天下有山-遁-君子以遠小人-不惡而嚴。" tabindex="-1">象曰：天下有山，遁，君子以遠小人，不惡而嚴。 <a class="header-anchor" href="#象曰-天下有山-遁-君子以遠小人-不惡而嚴。" aria-label="Permalink to “象曰：天下有山，遁，君子以遠小人，不惡而嚴。”">​</a></h3><p>“遠小人不惡而嚴”，惡讀為憎惡之惡，遠小人不可示此惡也，惡則患及之，又焉能遠!嚴之為言，敬小人而遠之之義也。</p><h3 id="初六-遁尾-厲-勿用有攸往。-象曰-遁尾之厲-不往何災也" tabindex="-1">初六，遁尾，厲，勿用有攸往。 象曰：遁尾之厲，不往何災也! <a class="header-anchor" href="#初六-遁尾-厲-勿用有攸往。-象曰-遁尾之厲-不往何災也" aria-label="Permalink to “初六，遁尾，厲，勿用有攸往。 象曰：遁尾之厲，不往何災也!”">​</a></h3><p>危而不往何也？遁既後時，［往］則取災，故知者違難在乎先幾。</p><h3 id="六二-執之用黃牛之革-莫之勝說。-象曰-執用黃牛-固志也。" tabindex="-1">六二，執之用黃牛之革，莫之勝說。 象曰：執用黃牛，固志也。 <a class="header-anchor" href="#六二-執之用黃牛之革-莫之勝說。-象曰-執用黃牛-固志也。" aria-label="Permalink to “六二，執之用黃牛之革，莫之勝說。 象曰：執用黃牛，固志也。”">​</a></h3><p>黃牛，中順也。陰邪浸長，二居君臣正合之位，戡難救時，莫若中順固志，使奸不能乾，不然，小人易間矣。</p><h3 id="九三-系遁-有疾厲。畜臣妾-吉。-象曰-系遁之厲-有疾憊也。-畜臣妾吉-不可大事也。" tabindex="-1">九三，系遁，有疾厲。畜臣妾，吉。 象曰：系遁之厲，有疾憊也。“畜臣妾吉”，不可大事也。 <a class="header-anchor" href="#九三-系遁-有疾厲。畜臣妾-吉。-象曰-系遁之厲-有疾憊也。-畜臣妾吉-不可大事也。" aria-label="Permalink to “九三，系遁，有疾厲。畜臣妾，吉。 象曰：系遁之厲，有疾憊也。“畜臣妾吉”，不可大事也。”">​</a></h3><p>為內之主，得位之正，立愛其下，畜臣妾之道盡矣，然以斯處遁，危疾宜焉。</p><h3 id="九四-好遁-君子吉-小人否。-象曰-君子好遁-小人否也。" tabindex="-1">九四，好遁，君子吉，小人否。 象曰：君子好遁，小人否也。 <a class="header-anchor" href="#九四-好遁-君子吉-小人否。-象曰-君子好遁-小人否也。" aria-label="Permalink to “九四，好遁，君子吉，小人否。 象曰：君子好遁，小人否也。”">​</a></h3><p>有應於陰，不惡而嚴，故曰“好遁”，小人暗於事幾，不忿怒成仇，則私溺為累矣。</p><h3 id="九五-嘉遁-貞吉。-象曰-嘉遁貞吉-以正志也。" tabindex="-1">九五，嘉遁，貞吉。 象曰：“嘉遁貞吉”，以正志也。 <a class="header-anchor" href="#九五-嘉遁-貞吉。-象曰-嘉遁貞吉-以正志也。" aria-label="Permalink to “九五，嘉遁，貞吉。 象曰：“嘉遁貞吉”，以正志也。”">​</a></h3><p>“嘉”“好”義同，然五居正處中，能正其志，故獲貞吉。</p><h3 id="上九-肥遁-無不利。-象曰-肥遁無不利-無所疑也。" tabindex="-1">上九，肥遁，無不利。 象曰：“肥遁無不利”，無所疑也。 <a class="header-anchor" href="#上九-肥遁-無不利。-象曰-肥遁無不利-無所疑也。" aria-label="Permalink to “上九，肥遁，無不利。 象曰：“肥遁無不利”，無所疑也。”">​</a></h3>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
